import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using correlation with outcome
    drivers = []
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for strong correlations with outcome
    corrs = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            corrs.append((abs(corr), fid, i))

    # Sort by absolute correlation strength
    corrs.sort(reverse=True)

    # If any clinical/cohort feature has strong correlation, use it as driver
    if corrs and corrs[0][0] > 0.1:
        drivers = [corrs[0][1]]

    # Select features based on t-test significance and correlation
    selected_features = []
    for i, fid in enumerate(feats.ids):
        t_stat = np.abs(np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i]))
        if t_stat > 0.5:
            selected_features.append(fid)

    # Remove near-duplicates (correlated features)
    selected_features = list(set(selected_features))

    # Build columns and products
    columns = tuple(selected_features[:10])  # Limit to top 10 features

    # Create interaction terms for highly correlated pairs
    products = []
    corr_pairs = [
        ('JEYQ18', 'KOW15'), ('KOW15', 'QCV2'), ('JEYQ18', 'QCV2'),
        ('KOW15', 'KQPY18'), ('JEYQ18', 'KQPY18'), ('QCV2', 'KQPY18'),
        ('XRVP10', 'DJDA15L'), ('KOW15', 'EOKC7'), ('JEYQ18', 'EOKC7')
    ]

    # Add products for correlated pairs that are also in our feature set
    for a, b in corr_pairs:
        if a in feats.ids and b in feats.ids:
            products.append((a, b))

    # Weighted score: use mutual information to assign weights
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical' and feats.types[i] != 'cohort':
            mi = mutual_info_classif(feats.x[:, i].reshape(-1, 1), feats.y)[0]
            loadings[fid] = mi

    return Design(drivers=tuple(drivers), columns=columns, products=tuple(products), loadings=loadings)

